import{t as l,g as f}from"./i18n.Lr-IErb8.js";async function p(){const s=document.getElementById("archives-list");if(!s)return;const u=f();try{const i=await(await fetch("/api/v1/articles?page_size=1000&status=published")).json();if(i.code===0&&i.data){const d=i.data.items;if(d.length===0){s.innerHTML=`<p style="text-align:center;color:var(--color-text-tertiary);padding:3rem 0;">${l("article.no_articles")}</p>`;return}const r={};for(const a of d){const o=a.published_at||a.created_at,c=new Date(o),t=c.getFullYear().toString(),e=(c.getMonth()+1).toString().padStart(2,"0");r[t]||(r[t]={}),r[t][e]||(r[t][e]=[]),r[t][e].push(a)}let n="";const m=Object.keys(r).sort((a,o)=>Number(o)-Number(a));for(const a of m){const o=Object.values(r[a]).reduce((t,e)=>t+e.length,0);n+='<div class="archive-year-group">',n+=`<h2 class="archive-year">${a}<span class="archive-year-count">${o} ${u==="zh"?"篇":"articles"}</span></h2>`;const c=Object.keys(r[a]).sort((t,e)=>Number(e)-Number(t));for(const t of c){n+='<div class="archive-month-group">',n+=`<h3 class="archive-month">${l(`month.${t}`)}</h3>`,n+='<ul class="archive-list" data-reveal-stagger>';for(const e of r[a][t]){const h=new Date(e.published_at||e.created_at),v=`${(h.getMonth()+1).toString().padStart(2,"0")}-${h.getDate().toString().padStart(2,"0")}`;n+=`<li data-reveal="fade-up"><span class="archive-date">${v}</span><a href="/articles/${e.slug}">${e.title}</a></li>`}n+="</ul></div>"}n+="</div>"}s.innerHTML=n,window.dispatchEvent(new CustomEvent("motion:refresh"))}}catch{s.innerHTML=`<p style="text-align:center;color:var(--color-text-tertiary);padding:3rem 0;">${l("common.load_failed")}</p>`}}p();document.addEventListener("locale-changed",()=>p());
